      ro: ["Cascada Penitente are o înălțime de aproximativ 60 de metri.", "Parcul a fost inaugurat ca rezervație naturală privată în 2004.", "Situat în departamentul Lavalleja, lângă Minas.", "Oferă activități de aventură precum rapel și tiroliană.", "Parcul acoperă o suprafață de aproximativ 200 de hectare.", "Infrastructura include un restaurant, cabane și o zonă de camping."],
      en: ["The Penitente Waterfall is approximately 60 meters high.", "The park was inaugurated as a private nature reserve in 2004.", "Located in the Lavalleja Department, near Minas.", "Offers adventure activities like rappelling and a zip-line.", "The park covers an area of approximately 200 hectares.", "Infrastructure includes a restaurant, cabins, and a camping area."],
      es: ["El nombre 'Penitente' proviene de una formación rocosa que recuerda a un monje rezando.", "El parque ofrece una de las tirolinas más largas de Uruguay con más de 300 metros de longitud.", "El centro de visitantes ha sido galardonado varias veces por su diseño moderno e integrado.", "La región pertenece a una de las formaciones geológicas más antiguas de Sudamérica."],
      pt: ["O nome 'Penitente' provém de uma formação rochosa que lembra um monge a rezar.", "O parque oferece uma das tirolesas mais longas do Uruguai, com mais de 300 metros de comprimento.", "O centro de visitantes foi premiado várias vezes pelo seu design moderno e integrado na paisagem.", "A região pertence às formações geológicas mais antigas da América do Sul."],
      fr: ["Le nom 'Penitente' vient d'une formation rocheuse évoquant un moine en prière.", "Le parc propose l'une des plus longues tyroliennes d'Uruguay, avec plus de 300 mètres de long.", "Le centre de visiteurs a été primé plusieurs fois pour son design moderne intégré au paysage.", "La région fait partie des formations géologiques les plus anciennes d'Amérique du Sud."],
